import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { supabase } from '../lib/supabase';
import toast from 'react-hot-toast';
import {
  Clock, Store, Shield, AlertTriangle, CheckCircle,
  CreditCard, ClipboardPaste, Plus, Save, Building2, Smartphone, Camera
} from 'lucide-react';

const PRICING = [
  { minStores: 1, maxStores: 1, monthly: 150, label: '1 Store' },
  { minStores: 2, maxStores: 2, monthly: 250, label: '2 Stores' },
  { minStores: 3, maxStores: 3, monthly: 580, label: '3 Stores' },
];

export default function Settings() {
  const {
    staff, storeId, availableStores, subscriptionStatus, trialDaysLeft,
    isLocked, checkSubscription, user, reloadStaff
  } = useAuth();

  // ----- Subscription (global) -----
  const [subscriptionEnd, setSubscriptionEnd] = useState(null);
  const [now, setNow] = useState(new Date());
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [smsText, setSmsText] = useState('');
  const [verifying, setVerifying] = useState(false);
  const [billingCycle, setBillingCycle] = useState('monthly');

  // ----- Company settings (per‑store) -----
  const [selectedStoreId, setSelectedStoreId] = useState(storeId);
  const [loading, setLoading] = useState(true);
  const [form, setForm] = useState({
    company_name: '',
    tpin: '',
    address: '',
    phone: '',
    email: '',
    business_mobile_money_number: '',
    local_currency: 'ZMW',
    receipt_footer: 'Thank you for your business!',
    vat_registered: false,
    vat_rate: '16',
    hardware_scanner: 'camera',
    low_stock_threshold: '5',
  });
  const [saving, setSaving] = useState(false);

  // ----- New store modal -----
  const [showNewStoreModal, setShowNewStoreModal] = useState(false);
  const [newStoreName, setNewStoreName] = useState('');

  const isAdmin = staff?.role === 'admin';
  const storeCount = availableStores?.length || 0;
  const maxStoresReached = storeCount >= 3;

  const plan = PRICING.find(p => storeCount >= p.minStores && storeCount <= p.maxStores) || null;
  const monthlyPrice = plan?.monthly || 0;
  const annualPrice = monthlyPrice * 10;
  const paymentAmount = billingCycle === 'monthly' ? monthlyPrice : annualPrice;
  const currency = form.local_currency || 'ZMW';
  const businessNumber = form.business_mobile_money_number || '097XXXXXXX';

  useEffect(() => {
    const timer = setInterval(() => setNow(new Date()), 60000);
    return () => clearInterval(timer);
  }, []);

  // Load company settings when store changes
  useEffect(() => {
    if (!selectedStoreId || !isAdmin) return;
    const load = async () => {
      setLoading(true);
      try {
        const { data } = await supabase
          .from('company_settings')
          .select('*')
          .eq('store_id', selectedStoreId)
          .single();
        if (data) {
          setForm({
            company_name: data.company_name || '',
            tpin: data.tpin || '',
            address: data.address || '',
            phone: data.phone || '',
            email: data.email || '',
            business_mobile_money_number: data.business_mobile_money_number || '',
            local_currency: data.local_currency || 'ZMW',
            receipt_footer: data.receipt_footer || 'Thank you for your business!',
            vat_registered: data.vat_registered || false,
            vat_rate: data.vat_rate ? String(data.vat_rate) : '16',
            hardware_scanner: data.hardware_scanner || 'camera',
            low_stock_threshold: data.low_stock_threshold ? String(data.low_stock_threshold) : '5',
          });
        }
      } catch (err) {
        console.error(err);
        toast.error('Failed to load store settings');
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [selectedStoreId, isAdmin]);

  // Subscription end date
  useEffect(() => {
    if (availableStores?.length > 0) {
      const end = availableStores[0]?.subscription_end_date;
      setSubscriptionEnd(end ? new Date(end) : null);
    }
  }, [availableStores]);

  // ----- Subscription helpers -----
  const formatTimeLeft = (endDate) => {
    const diff = endDate - now;
    if (diff <= 0) return { expired: true, text: 'Expired' };
    const days = Math.floor(diff / (1000 * 60 * 60 * 24));
    const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    return { expired: false, text: `${days}d ${hours}h remaining` };
  };
  const timeLeftInfo = subscriptionEnd ? formatTimeLeft(subscriptionEnd) : null;

  const handlePaste = async () => {
    try { setSmsText(await navigator.clipboard.readText()); toast.success('Pasted'); }
    catch { toast.error('Cannot access clipboard'); }
  };

  const extractSmsDetails = (text) => {
    const patterns = {
      transactionId: [/Txn\.?\s*ID\s*[:\-]?\s*([A-Z0-9.]+)/i, /Transaction\s*ID\s*[:\-]?\s*([A-Z0-9.]+)/i, /Trans\s*ID\s*[:\-]?\s*([A-Z0-9.]+)/i, /Ref\s*[:\-]?\s*([A-Z0-9.]+)/i],
      amount: [/Amount\s*[:\-]?\s*([\d,]+\.?\d*)/i, /ZMW\s*([\d,]+\.?\d*)/i, /K\s*([\d,]+\.?\d*)/i],
      senderName: [/from\s+([A-Za-z\s]+?)(?:\s+on|\s+at|\s+\.|\s+Ref|\s*$)/i],
      senderPhone: [/from\s+(\d{10,})/i, /(\d{10,})/],
    };
    let transactionId = null, amount = null, senderName = null, senderPhone = null;
    for (const regex of patterns.transactionId) { const m = text.match(regex); if (m) { transactionId = m[1].trim(); break; } }
    for (const regex of patterns.amount) { const m = text.match(regex); if (m) { amount = parseFloat(m[1].replace(/,/g, '')); break; } }
    for (const regex of patterns.senderName) { const m = text.match(regex); if (m) { senderName = m[1].trim(); break; } }
    for (const regex of patterns.senderPhone) { const m = text.match(regex); if (m) { senderPhone = m[1].trim(); break; } }
    return { transactionId, amount, senderName, senderPhone };
  };

  const handleVerifyPayment = async (e) => {
    e.preventDefault();
    if (!smsText.trim()) return toast.error('Paste SMS');
    setVerifying(true);
    try {
      const { transactionId, amount, senderName } = extractSmsDetails(smsText);
      if (!transactionId) throw new Error('Transaction ID not found');
      if (!amount) throw new Error('Amount not found');
      if (amount < paymentAmount) throw new Error(`Amount too low (expected ${paymentAmount} ZMW)`);

      const { data, error } = await supabase
        .from('mobile_money_transactions')
        .select('*')
        .eq('transaction_id', transactionId)
        .eq('status', 'pending')
        .single();
      if (error || !data) throw new Error('Transaction not found or already used');
      if (Math.abs(data.amount - amount) > 0.01) throw new Error('Amount mismatch');
      if (senderName && data.sender_name && !data.sender_name.toLowerCase().includes(senderName.toLowerCase())) {
        throw new Error('Sender name mismatch');
      }
      await supabase.from('mobile_money_transactions').update({ status: 'used' }).eq('id', data.id);

      const storeIds = availableStores.map(s => s.id);
      const endDate = new Date();
      endDate.setMonth(endDate.getMonth() + (billingCycle === 'monthly' ? 1 : 12));
      const { error: updateError } = await supabase
        .from('stores')
        .update({ subscription_status: 'active', subscription_end_date: endDate.toISOString(), subscription_plan: billingCycle, trial_started_at: null })
        .in('id', storeIds);
      if (updateError) throw updateError;

      await checkSubscription(storeId);
      toast.success(`Subscription activated for ${billingCycle === 'monthly' ? '1 month' : '12 months'}!`);
      setShowPaymentModal(false);
      setSmsText('');
    } catch (err) {
      toast.error(err.message);
    } finally {
      setVerifying(false);
    }
  };

  const handleSaveSettings = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      const payload = {
        ...form,
        store_id: selectedStoreId,
        vat_rate: parseFloat(form.vat_rate) || 16,
        low_stock_threshold: parseInt(form.low_stock_threshold, 10) || 5,
      };
      const { data: existing } = await supabase.from('company_settings').select('id').eq('store_id', selectedStoreId).single();
      let error;
      if (existing) {
        ({ error } = await supabase.from('company_settings').update(payload).eq('id', existing.id));
      } else {
        ({ error } = await supabase.from('company_settings').insert(payload));
      }
      if (error) throw error;
      toast.success('Settings saved');
    } catch (err) {
      toast.error(err.message);
    } finally {
      setSaving(false);
    }
  };

  const handleCreateStore = async (e) => {
    e.preventDefault();
    if (!newStoreName.trim()) return toast.error('Store name required');
    if (maxStoresReached) return toast.error('Maximum of 3 stores reached');
    try {
      const { data: store, error: storeError } = await supabase
        .from('stores')
        .insert({ name: newStoreName.trim(), subscription_status: 'trialing', trial_started_at: new Date().toISOString() })
        .select('id').single();
      if (storeError) throw storeError;

      await supabase.from('store_admins').insert({ user_id: user.id, store_id: store.id });
      await supabase.from('company_settings').insert({
        store_id: store.id,
        company_name: newStoreName.trim(),
        receipt_footer: 'Thank you for your business!',
      });
      await supabase.from('staff').insert({
        user_id: user.id,
        store_id: store.id,
        full_name: user.user_metadata?.full_name || 'Owner',
        email: user.email,
        role: 'admin',
        is_active: true,
      });
      toast.success('New store created!');
      setShowNewStoreModal(false);
      setNewStoreName('');
      await reloadStaff();
      setSelectedStoreId(store.id);
    } catch (err) {
      toast.error(err.message);
    }
  };

  if (!isAdmin) return <div className="p-8 text-red-600">Access Denied</div>;
  if (loading && !selectedStoreId) return <div className="p-8">Loading...</div>;

  return (
    <div className="p-4 h-full overflow-y-auto max-w-2xl mx-auto space-y-8">
      {/* Subscription Card */}
      <div className="bg-white rounded-2xl shadow-lg border border-gray-100 p-6">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-xl font-bold flex items-center gap-2"><Shield className="text-green-600" /> Current Package</h2>
          <span className="text-sm text-gray-500">{storeCount} store{storeCount > 1 ? 's' : ''}</span>
        </div>
        {plan && (
          <div className="mb-4">
            <p className="text-3xl font-bold">{plan.label}</p>
            <p className="text-lg text-green-700">ZMW {plan.monthly} <span className="text-gray-500 text-sm">/ month</span></p>
          </div>
        )}
        <div className="flex items-center gap-2 mb-4">
          {subscriptionStatus === 'active' && <CheckCircle className="text-green-600" size={20} />}
          {subscriptionStatus === 'trialing' && <Clock className="text-blue-600" size={20} />}
          {subscriptionStatus === 'expired' && <AlertTriangle className="text-red-600" size={20} />}
          {subscriptionStatus === 'pending' && <Clock className="text-yellow-600" size={20} />}
          <span className={`font-semibold ${
            subscriptionStatus === 'active' ? 'text-green-700' : subscriptionStatus === 'trialing' ? 'text-blue-700' : 'text-red-700'
          }`}>
            {subscriptionStatus === 'active' && 'Active'}
            {subscriptionStatus === 'trialing' && `Trial — ${trialDaysLeft} day${trialDaysLeft !== 1 ? 's' : ''} left`}
            {subscriptionStatus === 'expired' && 'Expired'}
            {subscriptionStatus === 'pending' && 'Pending'}
          </span>
        </div>
        {subscriptionStatus === 'active' && timeLeftInfo && (
          <div className="mb-4 p-3 bg-green-50 rounded-lg text-sm">
            <Clock className="inline mr-1 text-green-600" size={16} /> {timeLeftInfo.text}
            {subscriptionEnd && <span className="ml-2 text-gray-500">Expires {subscriptionEnd.toLocaleDateString()}</span>}
          </div>
        )}
        {isLocked && (
          <div className="mb-4 p-3 bg-red-50 text-red-700 rounded-lg text-sm flex items-center gap-2">
            <AlertTriangle size={16} /> Access restricted — subscription required.
          </div>
        )}
        <button onClick={() => setShowPaymentModal(true)} className="w-full bg-green-600 text-white py-3 rounded-lg font-medium flex items-center justify-center gap-2 hover:bg-green-700">
          <CreditCard size={20} /> {subscriptionStatus === 'active' ? 'Renew / Upgrade' : 'Subscribe Now'}
        </button>
      </div>

      {/* Store Selector */}
      <div className="bg-white rounded-2xl shadow-lg border border-gray-100 p-6">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-xl font-bold flex items-center gap-2"><Store size={20} /> Your Stores</h2>
          <button
            onClick={() => setShowNewStoreModal(true)}
            disabled={maxStoresReached}
            className={`px-4 py-2 rounded-lg flex items-center gap-2 text-white ${maxStoresReached ? 'bg-gray-400 cursor-not-allowed' : 'bg-blue-600 hover:bg-blue-700'}`}
            title={maxStoresReached ? 'Maximum 3 stores reached' : 'Add a new store'}
          >
            <Plus size={18} /> Add Store
          </button>
        </div>
        {storeCount > 0 ? (
          <div className="flex flex-wrap gap-2">
            {availableStores.map(s => (
              <button
                key={s.id}
                onClick={() => setSelectedStoreId(s.id)}
                className={`px-4 py-2 rounded-full text-sm font-medium transition ${s.id === selectedStoreId ? 'bg-green-600 text-white shadow' : 'bg-gray-100 text-gray-800 hover:bg-gray-200'}`}
              >
                {s.name}
              </button>
            ))}
          </div>
        ) : (
          <p className="text-gray-500 text-sm">No stores yet. Create your first store!</p>
        )}
      </div>

      {/* Company Settings Form */}
      {selectedStoreId && (
        <div className="bg-white rounded-2xl shadow-lg border border-gray-100 p-6">
          <h2 className="text-xl font-bold mb-4 flex items-center gap-2"><Building2 size={20} /> Company Settings</h2>
          <form onSubmit={handleSaveSettings} className="space-y-4">
            <input placeholder="Company Name" value={form.company_name} onChange={e => setForm({...form, company_name: e.target.value})} className="w-full p-2 border rounded" />
            <input placeholder="TPIN" value={form.tpin} onChange={e => setForm({...form, tpin: e.target.value})} className="w-full p-2 border rounded" />
            <input placeholder="Address" value={form.address} onChange={e => setForm({...form, address: e.target.value})} className="w-full p-2 border rounded" />
            <input placeholder="Phone" value={form.phone} onChange={e => setForm({...form, phone: e.target.value})} className="w-full p-2 border rounded" />
            <input placeholder="Email" value={form.email} onChange={e => setForm({...form, email: e.target.value})} className="w-full p-2 border rounded" />

            {/* Receipt & Tax */}
            <div className="border-t pt-4">
              <h3 className="font-medium mb-2">Receipt & Tax Settings</h3>
              <input placeholder="Receipt Footer" value={form.receipt_footer} onChange={e => setForm({...form, receipt_footer: e.target.value})} className="w-full p-2 border rounded mb-2" />
              <label className="flex items-center gap-2 mb-2">
                <input type="checkbox" checked={form.vat_registered} onChange={e => setForm({...form, vat_registered: e.target.checked})} />
                VAT Registered
              </label>
              {form.vat_registered && (
                <input type="number" step="0.1" placeholder="VAT Rate (%)" value={form.vat_rate} onChange={e => setForm({...form, vat_rate: e.target.value})} className="w-full p-2 border rounded" />
              )}
            </div>

            {/* Hardware Scanner */}
            <div className="border-t pt-4">
              <h3 className="font-medium mb-2 flex items-center gap-1"><Camera size={16} /> Barcode Scanner</h3>
              <select value={form.hardware_scanner} onChange={e => setForm({...form, hardware_scanner: e.target.value})} className="w-full p-2 border rounded">
                <option value="camera">Camera (built-in)</option>
                <option value="bluetooth">Bluetooth Scanner</option>
                <option value="usb">USB Scanner</option>
              </select>
            </div>

            {/* Low Stock Threshold */}
            <div className="border-t pt-4">
              <h3 className="font-medium mb-2">Inventory Alerts</h3>
              <label className="text-sm text-gray-500 mb-1 block">Low Stock Threshold</label>
              <input type="number" min="0" step="1" value={form.low_stock_threshold} onChange={e => setForm({...form, low_stock_threshold: e.target.value})} className="w-full p-2 border rounded" />
              <p className="text-xs text-gray-400 mt-1">Products with stock ≤ this value will be shown on the Dashboard.</p>
            </div>

            {/* Mobile Money */}
            <div className="border-t pt-4">
              <h3 className="font-medium mb-2 flex items-center gap-1"><Smartphone size={16} /> Mobile Money Settings</h3>
              <input placeholder="Business Number" value={form.business_mobile_money_number} onChange={e => setForm({...form, business_mobile_money_number: e.target.value})} className="w-full p-2 border rounded mb-2" />
              <input placeholder="Currency (ZMW)" value={form.local_currency} onChange={e => setForm({...form, local_currency: e.target.value})} className="w-full p-2 border rounded" />
            </div>

            <button type="submit" disabled={saving} className="w-full bg-green-600 text-white py-3 rounded-lg font-medium flex items-center justify-center gap-2 hover:bg-green-700">
              <Save size={18} /> {saving ? 'Saving...' : 'Save Settings'}
            </button>
          </form>
        </div>
      )}

      {/* Payment Modal (unchanged) */}
      {showPaymentModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl w-full max-w-md">
            <div className="p-4 border-b"><h2 className="text-xl font-bold">Activate Subscription</h2></div>
            <div className="p-4 space-y-4">
              <div className="bg-blue-50 p-3 rounded">
                <p className="font-medium">Your Plan: {plan.label}</p>
                <p className="text-sm mt-1">Monthly: {currency} {monthlyPrice} | Annual: {currency} {annualPrice}</p>
              </div>
              <div>
                <label className="block text-sm font-medium mb-2">Choose Billing Cycle</label>
                <div className="flex gap-4">
                  <label className="flex items-center gap-1 cursor-pointer">
                    <input type="radio" name="billingCycle" value="monthly" checked={billingCycle === 'monthly'} onChange={() => setBillingCycle('monthly')} />
                    <span>Monthly ({currency} {monthlyPrice})</span>
                  </label>
                  <label className="flex items-center gap-1 cursor-pointer">
                    <input type="radio" name="billingCycle" value="annual" checked={billingCycle === 'annual'} onChange={() => setBillingCycle('annual')} />
                    <span>Annual ({currency} {annualPrice})</span>
                  </label>
                </div>
              </div>
              <div className="bg-blue-50 p-3 rounded">
                <p className="font-medium">Send <span className="text-xl font-bold">{currency} {paymentAmount}</span> to:</p>
                <p className="text-2xl font-bold mt-1">{businessNumber}</p>
                <p className="text-xs mt-2 text-gray-500">Use Airtel Money and keep the confirmation SMS.</p>
              </div>
              <textarea value={smsText} onChange={e => setSmsText(e.target.value)} rows={3} className="w-full p-2 border rounded font-mono text-sm" placeholder="Paste confirmation SMS here" />
              <div className="flex gap-2">
                <button onClick={handlePaste} className="px-3 py-1.5 bg-gray-200 rounded flex items-center gap-1"><ClipboardPaste size={14} /> Paste</button>
                <button onClick={handleVerifyPayment} disabled={verifying} className="flex-1 bg-green-600 text-white py-1.5 rounded">{verifying ? 'Verifying...' : 'Verify & Activate'}</button>
              </div>
            </div>
            <div className="p-3 border-t flex justify-end">
              <button onClick={() => setShowPaymentModal(false)} className="px-4 py-1.5 border rounded">Cancel</button>
            </div>
          </div>
        </div>
      )}

      {/* New Store Modal */}
      {showNewStoreModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl w-full max-w-md">
            <div className="p-4 border-b"><h2 className="text-xl font-bold">Add New Store</h2></div>
            <form onSubmit={handleCreateStore} className="p-4 space-y-4">
              <input placeholder="Store Name" value={newStoreName} onChange={e => setNewStoreName(e.target.value)} className="w-full p-2 border rounded" required autoFocus />
              {maxStoresReached && <p className="text-red-500 text-sm">You've reached the maximum of 3 stores.</p>}
              <div className="flex gap-2">
                <button type="button" onClick={() => setShowNewStoreModal(false)} className="flex-1 py-2 border rounded">Cancel</button>
                <button type="submit" disabled={maxStoresReached} className="flex-1 py-2 bg-blue-600 text-white rounded">Create Store</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
